-- STEP BOUNDARY --

-- STEP 3: query [aktsomhetskart_jord_flomskred]
SELECT objid, skredtype, ST_AsGeoJSON(ST_Transform(geometri,4326)) AS geom_geojson FROM aktsomhetskartforjordogflomskred_83e4643e9cbd4a3a98fd29cb231c74.aktsomhetsomrjordogflomskred WHERE ST_Intersects(geometri, (SELECT omrade FROM kommuner_627ee106072240e99d2b21ec4717bf01.kommune WHERE kommunenummer = '0301'));

